// 0FDC:134B: void Restore_Mission_Map_View_After_Combat()
// Called from:
//      Mech_Mission_0629, after combat in training missions 2..7
// Sol: Summary: Return to the mission map after combat.
// Sol: Outline: Restore the mission's world position and map caches, then rebuild the exploration display.
void Restore_Mission_Map_View_After_Combat()
{
	// Sol: Fresh whole-body ASM match, including Y+2 and conditional +0F80 wrap.
	// Sol: The training missions keep Jason's mech in combatant/mech slot zero.
	// Sol: Any assignment other than the on-foot sentinel follows this branch.
	if (seg3092->Infantry[Character_Jason].Piloting != Character_OnFoot) //3092:C620
	{
		seg246C->CrescentHawk_MapPositionX =
			seg3092->CharacterPosX_Mech[Character_Jason]; //3092:4004 -> 246C:A44B
		seg246C->CrescentHawk_MapPositionY =
			seg3092->CharacterPosY_Mech[Character_Jason] + 0x0002; //3092:4036 -> 246C:A44D

		// Sol: Adding two can cross local Y=7F. Adding 0F80 then converts the
		// Sol: noncanonical xx80/xx81 value into the next packed map row's 00/01.
		if ((seg246C->CrescentHawk_MapPositionY & Char_MostSignificantBit) != FALSE)
			seg246C->CrescentHawk_MapPositionY += 0x0F80;
	}
	else
	{
		seg246C->CrescentHawk_MapPositionX =
			seg3092->CharacterPosX_OnFoot[Character_Jason]; //3092:400C -> 246C:A44B
		seg246C->CrescentHawk_MapPositionY =
			seg3092->CharacterPosY_OnFoot[Character_Jason]; //3092:403E -> 246C:A44D
	}

	// Sol: Rebuild and present the exploration view centred on the restored anchor.
	PosXY_OffsetGrid(
		seg246C->CrescentHawk_MapPositionX,
		seg246C->CrescentHawk_MapPositionY);
	Copy_Data_To_GraphicsMemory();
	Draw_Infantry_And_Mechs();
	EGA_DrawBox_Wrapper();
}

// 0FDC:13DE: void Distribute_Purchased_Armour(Stack WORD HeldArmourType, Stack WORD HeldArmourValue)
// Called from:
//      Citadel_Building_Dialogs
// Sol: Summary: Assign purchased armour to party members.
// Sol: Outline: Select eligible recipients, update their armour records, and repeat or finish according to the menu response.
void Distribute_Purchased_Armour(
	unsigned short HeldArmourType,
	unsigned short HeldArmourValue)
{
	// TODO Sol: Fresh ASM audit: retain FAR3092 recipient views and CBW before
	// TODO Sol: character-name/armour-description indexing; DS:1667 starts with
	// TODO Sol: a space missing from the current " to:" literal. See audit report.
	// Sol: The original stack array contains eight WORD party-record IDs and is
	// Sol: initialized to FFFF before being compacted to only living members.
	unsigned short PartyMemberByMenuIndex[8];
	for (unsigned short MenuIndex = 0x0000; MenuIndex < 0x0008; MenuIndex++)
		PartyMemberByMenuIndex[MenuIndex] = 0xFFFF;

	unsigned short LivingPartyMemberCount = 0x0000;
	for (unsigned short PartyMemberId = 0x0000; PartyMemberId < 0x0008; PartyMemberId++)
	{
		if (seg3092->Infantry[PartyMemberId].Name != Character_Dead)
			PartyMemberByMenuIndex[LivingPartyMemberCount++] = PartyMemberId;
	}

	// Sol: The former pseudo-C reversed this condition. A nonzero armour type is
	// Sol: the item currently being held for assignment; type zero ends the chain.
	while (HeldArmourType != ArmourType_None)
	{
		unsigned short MenuChoice;
		if (LivingPartyMemberCount <= 0x0001)
		{
			// Sol: With zero or one living member the executable silently equips
			// Sol: Jason and discards whatever armour record zero previously held.
			seg3092->Infantry[Character_Jason].ArmourType =
				(unsigned char)HeldArmourType;
			seg3092->Infantry[Character_Jason].ArmourValue =
				(unsigned char)HeldArmourValue;
			MenuChoice = LivingPartyMemberCount;
		}
		else
		{
			Draw_Top_Graphic_Sidebar();
			Display_Text_From_Memory("Give "); //3EDB:1661
			Display_Text_From_Memory(
				seg3EDB->ArmourTextDescription[HeldArmourType]);
			Display_Text_From_Memory(" to:\r"); //3EDB:1667

			for (unsigned short MenuIndex = 0x0000;
				 MenuIndex < LivingPartyMemberCount;
				 MenuIndex++)
			{
				Infantry* PartyMember =
					&seg3092->Infantry[PartyMemberByMenuIndex[MenuIndex]];
				unsigned char CharacterNameId = PartyMember->Name;
				if (CharacterNameId != Character_Dead)
				{
					Display_Text_From_Memory(
						seg3EDB->CharacterNameList[CharacterNameId]);
					seg3092->HorizontalLine_Offset = 0x000A;
					Display_Text_From_Memory(
						seg3EDB->ArmourTextDescription[PartyMember->ArmourType]);
					Display_Text_4FA0_Value(); //3EDB:4FA0 is carriage return
				}
			}

			Display_Text_From_Memory("Drop it\r\r\rArmor points left: "); //3EDB:166D
			Display_Text_Dynamic_Value(HeldArmourValue);
			seg305B->w00D6 = LivingPartyMemberCount + 1;
			MenuChoice = Display_Menu_Choices_And_Check(0x04);
		}

		if (MenuChoice == LivingPartyMemberCount)
		{
			HeldArmourType = ArmourType_None;
		}
		else
		{
			Infantry* Recipient =
				&seg3092->Infantry[PartyMemberByMenuIndex[MenuChoice]];
			signed short DisplacedArmourType = (signed char)Recipient->ArmourType;
			signed short DisplacedArmourValue = (signed char)Recipient->ArmourValue;

			Recipient->ArmourType = (unsigned char)HeldArmourType;
			Recipient->ArmourValue = (unsigned char)HeldArmourValue;

			// Sol: The exchange has already occurred when this warning is shown.
			if (HeldArmourType == DisplacedArmourType)
			{
				Display_Text_At_2867(
					"He already has that type of armor.", 0x00, 0x14); //3EDB:168B
				Wait_For_50Hz_Then_Check_Input();
				Keyboard_Get_ASCII_Hex_Input();
			}

			// Sol: The recipient's previous armour becomes the next held item. If
			// Sol: its type is None (zero), the transfer chain ends automatically.
			HeldArmourType = DisplacedArmourType;
			HeldArmourValue = DisplacedArmourValue;
		}
	}
}

