// 0FDC:17B9: void Talk_To_Building_Occupants()
// Called from:
//      Citadel_Building_Dialogs
// Sol: Summary: Dispatch conversations with a building's occupants.
// Sol: Outline: Inspect the current building and story state, then display or invoke the appropriate conversation.
void Talk_To_Building_Occupants()
{
	// TODO Sol: Fresh ASM audit: roaming NPC views are FAR3092, not near DS.
	// TODO Sol: DS:172D has two spaces after '?'; current literal has only one.
	// Sol: The peculiar last-waiting-waypoint Rick gate is confirmed, not fixed.
	// Sol: Each BLD's "Talk to others" branch first writes D319. The value is
	// Sol: both a purpose-text index and a BLD ID/category. Find which of the
	// Sol: map's first eight exterior building slots resolves to that ID.
	unsigned short CurrentBuildingSlot = 0x0000;
	while (CurrentBuildingSlot < 0x0008
		&& seg3092->AlternativeBldByBuildingId[CurrentBuildingSlot]
			!= seg3092->NpcActivityBuildingId)
	{
		CurrentBuildingSlot++;
	}

	Draw_Top_Graphic_Sidebar();
	unsigned char NpcWaitingInBuilding[8];
	unsigned short WaitingNpcCount = 0x0000;
	unsigned short LastWaitingNpcWaypoint;

	for (unsigned short NpcSlot = 0x0000; NpcSlot < 0x0008; NpcSlot++)
	{
		NpcWaitingInBuilding[NpcSlot] = FALSE;
		RoamingMapNpcRecordView* Npc = (RoamingMapNpcRecordView*)(
			(unsigned char*)&seg3092->EnemyInfantryPosX + (NpcSlot * 0x1A));

		// Sol: A nonzero delay means the NPC is waiting off-map at the high-nibble
		// Sol: waypoint. Delay zero is the travelling/on-map state.
		if (Npc->MovementDelay != 0x00)
		{
			LastWaitingNpcWaypoint = (Npc->WaypointPair >> 4) & 0x07;
			if (LastWaitingNpcWaypoint == CurrentBuildingSlot)
			{
				NpcWaitingInBuilding[NpcSlot] = TRUE;
				WaitingNpcCount++;
			}
		}
	}

	if (WaitingNpcCount == 0x0000)
	{
		Display_Text_From_Memory(
			"Nobody here seems interested in talking to you."); //3EDB:16DE
		Keyboard_Get_ASCII_Hex_Input();
		return;
	}

	Display_Text_From_Memory("You look around and see:\r"); //3EDB:170E
	for (unsigned short NpcSlot = 0x0000; NpcSlot < 0x0008; NpcSlot++)
	{
		if (NpcWaitingInBuilding[NpcSlot] != FALSE)
		{
			Display_Text_From_Memory(seg246C->MapCharacterNames[NpcSlot]);
			Display_Text_4FA0_Value();
		}
	}

	Display_Text_From_Memory("Done"); //3EDB:1728
	seg305B->w01D6 = WaitingNpcCount + 1;
	unsigned short SelectedOccupant = Display_Menu_Choices_And_Check(0x14);
	if (SelectedOccupant == WaitingNpcCount)
		return;

	// TODO Sol: Preserve this peculiar original condition exactly. It uses the
	// TODO Sol: last waiting NPC's waypoint, rather than the current building or
	// TODO Sol: selected NPC. See Astra candidate A-007.
	if (seg3092->HoldRickAtlasUntilLoungeConversation != FALSE
	 && LastWaitingNpcWaypoint == 0x0007
	 && SelectedOccupant == 0x0000
	 && NpcWaitingInBuilding[0] != FALSE)
	{
		seg3092->RickAtlasConversationTriggered = TRUE;
		RoamingMapNpcRecordView* FirstNpc = (RoamingMapNpcRecordView*)
			&seg3092->EnemyInfantryPosX;
		FirstNpc->MovementDelay = 0x00;
		return;
	}

	seg3092->RickAtlasConversationTriggered = FALSE;
	Draw_Top_Graphic_Sidebar();
	if (seg3092->Kurita_DestroyedCitadel != FALSE)
	{
		// Sol: After the Citadel is destroyed, occupants give one of eight
		// Sol: generic dismissive replies; the selected NPC otherwise has no effect.
		unsigned short ReplyIndex = Rand_0x00_to_0xFF() & 0x07;
		Display_Text_From_Memory(
			seg3EDB->DestroyedCitadelNpcReplyText[ReplyIndex]);
		Keyboard_Get_ASCII_Hex_Input();
		return;
	}

	Display_Text_From_Memory(
		"Hi, Jason, how are you? I just stopped in here to "); //3EDB:172D
	unsigned short ActivityId = (unsigned short)(signed char)
		seg3092->NpcActivityBuildingId;
	Display_Text_From_Memory(seg3EDB->NpcActivityReasonText[ActivityId]);
	Display_Text_From_Memory(
		"  After I'm done here, I'm going over to the "); //3EDB:1761

	// Sol: The menu is compact, but NPC route records retain their original slot.
	// Sol: DEC/JNS in the executable selects the Nth marked slot below.
	signed short RemainingChoice = SelectedOccupant;
	for (unsigned short NpcSlot = 0x0000; NpcSlot < 0x0008; NpcSlot++)
	{
		if (NpcWaitingInBuilding[NpcSlot] != FALSE && --RemainingChoice < 0)
		{
			RoamingMapNpcRecordView* SelectedNpc = (RoamingMapNpcRecordView*)(
				(unsigned char*)&seg3092->EnemyInfantryPosX + (NpcSlot * 0x1A));
			unsigned short DestinationBuildingSlot = SelectedNpc->WaypointPair & 0x07;
			Display_Text_From_Memory(
				seg246C->MapBuildingNames[DestinationBuildingSlot]);
			Display_Text_From_Memory("."); //3EDB:178F
			Keyboard_Get_ASCII_Hex_Input();
			return;
		}
	}
}

