// 0FDC:1D30: void Load_And_Decode_Indexed_BLD_1D30(unsigned short BldFileId)
// Called from:
//      Interact_with_BLD
//      Mech_Mission_0629
// Sol: Summary: Load and decode a selected building script.
// Sol: Outline: Resolve the filename table entry, read the original BLD, and decode it into the shared script buffer.
void Load_And_Decode_Indexed_BLD_1D30(unsigned short BldFileId)
{
	// Sol: Fresh whole-body ASM match under native WORD/FAR address arithmetic.
	// Sol: Signed JL disk gates are equivalent to these unsigned tests for all
	// Sol: WORD IDs; filename-table byte offsets must still wrap before lookup.
	// Sol: Decode all 2328h bytes, clear cache flag, and .dis return tail compared.
	// Sol: Select logical Game Disk 1 first. TRAINING/CITADEL and BLD IDs
	// Sol: 11h-19h are stored on Disk 2; IDs 02h-10h remain on Game Disk 1.
	Select_Game_Disk_And_Drive_28CC(0x0001);
	if (BldFileId < 0x0002 || BldFileId >= 0x0011)
		Select_Game_Disk_And_Drive_28CC(0x0002);

	seg3092->BLD_FileIndex = BldFileId;
	Load_File_To_Memory(
		seg3EDB->BldFileNameById[BldFileId],
		&seg3092->BTStatsORBLDMemoryLocation[0]);

	// Sol: Decode in place. Addition precedes XOR and byte assignment provides
	// Sol: the original 8-bit wrap. The fixed span intentionally exceeds every
	// Sol: shipped length-prefixed BLD payload; see QUIRK-001.
	for (unsigned short BufferOffset = 0x0000;
		 BufferOffset < BLD_FIXED_DECODE_SPAN;
		 BufferOffset++)
	{
		seg3092->BTStatsORBLDMemoryLocation[BufferOffset] = (unsigned char)(
			(seg3092->BTStatsORBLDMemoryLocation[BufferOffset] + 0x29) ^ 0xE9);
	}

	// Sol: BLD data now occupies the shared buffer; BTSTATS must be reloaded
	// Sol: before its next use.
	seg3092->BTStatsAssetLoaded = FALSE;
}

